class Solution {
public:
    int nthUglyNumber(int n) {
        vector<int> ugly(n, 1);
        int i2 = 0, i3 = 0, i5 = 0;
        for (int i = 1; i < n; ++i) {
            int next2 = ugly[i2] * 2;
            int next3 = ugly[i3] * 3;
            int next5 = ugly[i5] * 5;
            int next_val = min({next2, next3, next5});
            ugly[i] = next_val;
            if (next_val == next2) i2++;
            if (next_val == next3) i3++;
            if (next_val == next5) i5++;
        }
        return ugly[n - 1];
    }
};

class Solution {
    public int nthUglyNumber(int n) {
        int[] ugly = new int[n];
        ugly[0] = 1;
        int i2 = 0, i3 = 0, i5 = 0;
        for (int i = 1; i < n; i++) {
            int next2 = ugly[i2] * 2;
            int next3 = ugly[i3] * 3;
            int next5 = ugly[i5] * 5;
            int next_val = Math.min(next2, Math.min(next3, next5));
            ugly[i] = next_val;
            if (next_val == next2) i2++;
            if (next_val == next3) i3++;
            if (next_val == next5) i5++;
        }
        return ugly[n - 1];
    }
}

